static void render_sym_layer_guide(void) {
    oled_set_cursor(0, 7);
    oled_write_P(PSTR("    {  &  * (   }  "), false);
    oled_set_cursor(0, 8);
    oled_write_P(PSTR("    :  $  %  ^  +  "), false);
    oled_set_cursor(0, 9);
    oled_write_P(PSTR("    ~  !  @  #  |  "), false);
    oled_set_cursor(0, 10);
    oled_write_P(PSTR("          ~  _  ) "), false);
}

