static void render_status_bar(void) {
    uint8_t mods = get_mods() | get_oneshot_mods();

    oled_set_cursor(0, 14);

    oled_write_P(PSTR("MODS: "), false);
    oled_write_P((mods & MOD_MASK_SHIFT) ? PSTR("SFT ") : PSTR("--- "), false);
    oled_write_P((mods & MOD_MASK_CTRL) ? PSTR("CTL ") : PSTR("--- "), false);
    oled_write_P((mods & MOD_MASK_ALT) ? PSTR("ALT ") : PSTR("--- "), false);
    oled_write_P((mods & MOD_MASK_GUI) ? PSTR("GUI ") : PSTR("--- "), false);

    oled_set_cursor(0, 12);
    oled_write_P(PSTR("--------------------"), false);
}

static void render_mouse_status(void) {
    uint16_t current_cpi = pointing_device_get_cpi();

    bool is_sniping = dilemma_get_pointer_sniping_enabled();

    char mouse_str[21];

    snprintf(mouse_str, sizeof(mouse_str), "DPI: %d %s", current_cpi, is_sniping ? "[SNIP]" : "      ");

    oled_set_cursor(0, 13);
    oled_write(mouse_str, false);
}

bool oled_task_user(void) {
    switch (get_highest_layer(layer_state)) {
        case LAYER_BASE:
            render_base();
            render_clear_guides();
            break;
        case LAYER_FUNCTION:
            render_function();
            render_function_layer_guide();
            break;
        case LAYER_NAVIGATION:
            render_navigation();
            render_navigation_layer_guide();
            break;
        case LAYER_MEDIA:
            render_media();
            render_media_layer_guide();
            break;
        case LAYER_POINTER:
            render_mouse();
            render_pointer_layer_guide();
            break;
        case LAYER_NUMERAL:
            render_num();
            render_num_layer_guide();
            break;
        case LAYER_SYMBOLS:
            render_sym();
            render_sym_layer_guide();
            break;
        case LAYER_MACROS:
            render_macro_layer_guide();
        default:
            render_base();
            render_clear_guides();
    }

    render_mouse_status();
    render_status_bar();

    oled_set_cursor(0, 15);
    led_t led_state = host_keyboard_led_state();
    oled_write_P(led_state.num_lock ? PSTR("NUM ") : PSTR("    "), false);
    oled_write_P(led_state.caps_lock ? PSTR("CAPS ") : PSTR("     "), false);
    oled_write_P(led_state.scroll_lock ? PSTR("SCR ") : PSTR("    "), false);

#    ifdef WPM_ENABLE
    oled_set_cursor(14, 15);
    uint8_t wpm = get_current_wpm();
    char    wpm_str[10];
    snprintf(wpm_str, sizeof(wpm_str), "WPM %03d", wpm);
    oled_write(wpm_str, false);
#    endif

    return false;
}
#endif
